package com.bank.choice;

import java.util.*;
import java.util.logging.*;

public class MessagingChoiceDemo {
    private static final Logger log = Logger.getLogger(MessagingChoiceDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        MessagingAdvisor advisor = new MessagingAdvisor(1000);

        List<Workload> workloads = List.of(
            // name, msgsPerSec, synchronousReply, needsPriority, manyIndependentConsumers, needsReplay
            new Workload("Card authorization (Rajesh swipe)", 500, true, false, false, false),
            new Workload("End-of-day summary emails", 2, false, false, false, false),
            new Workload("VIP urgent wire transfer", 5, false, true, false, false),
            new Workload("Transaction firehose (analytics+fraud+ledger)", 20000, false, false, true, true)
        );

        for (Workload w : workloads) {
            String recommendation = advisor.recommend(w);
            log.info(() -> w.getName() + " → " + recommendation);
        }
    }
}

