class Workload {
    private final String name;
    private final int msgsPerSec;
    private final boolean synchronousReply;
    private final boolean needsPriority;
    private final boolean manyIndependentConsumers;
    private final boolean needsReplay;
    Workload(String name, int msgsPerSec, boolean synchronousReply, boolean needsPriority,
             boolean manyIndependentConsumers, boolean needsReplay) {
        this.name = name; this.msgsPerSec = msgsPerSec; this.synchronousReply = synchronousReply;
        this.needsPriority = needsPriority; this.manyIndependentConsumers = manyIndependentConsumers;
        this.needsReplay = needsReplay;
    }
    String getName() { return name; }
    int getMsgsPerSec() { return msgsPerSec; }
    boolean isSynchronousReply() { return synchronousReply; }
    boolean isNeedsPriority() { return needsPriority; }
    boolean isManyIndependentConsumers() { return manyIndependentConsumers; }
    boolean isNeedsReplay() { return needsReplay; }
}

// ─── Would be in service/MessagingAdvisor.java in a real project ───
class MessagingAdvisor {
    private final int kafkaThroughputThreshold;
    MessagingAdvisor(int kafkaThroughputThreshold) {
        this.kafkaThroughputThreshold = kafkaThroughputThreshold;
    }

    String recommend(Workload w) {
        if (w.isSynchronousReply())
            return "NOT Kafka — use REST/gRPC (caller needs an immediate reply)";
        if (w.isNeedsPriority())
            return "NOT Kafka — use RabbitMQ/ActiveMQ (native message priority)";
        if (w.getMsgsPerSec() < kafkaThroughputThreshold
                && !w.isManyIndependentConsumers() && !w.isNeedsReplay())
            return "NOT Kafka — use a managed queue (SQS) (low volume, simple decoupling)";
        if (w.isManyIndependentConsumers() || w.isNeedsReplay()
                || w.getMsgsPerSec() >= kafkaThroughputThreshold)
            return "USE Kafka (high throughput / replay / many independent consumers)";
        return "NOT Kafka — simpler tool fits";
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
